<script setup lang="ts">
// Add admin (username given here) or reset / change a password. The
// password is generated by the server unless one is entered (8+ characters,
// at most 72 UTF-8 bytes). Resolves with what the server returned.
import { computed, nextTick, onMounted, ref } from 'vue';
import { Eye, EyeOff, KeyRound, UserPlus } from 'lucide-vue-next';
import Modal from '@/components/ui/Modal.vue';
import Callout from '@/components/ui/Callout.vue';
import Toggle from '@/components/ui/Toggle.vue';
import Spinner from '@/screens/server/parts/Spinner.vue';
import { useApi } from '@/stores/session';
import { t } from '@/lib/i18n';
import { MAX_PASSWORD_BYTES, MIN_PASSWORD_LENGTH, passwordProblem, toPasswordResult, type PasswordResult } from './passwords';

const props = defineProps<{
  /** Absent: add an admin. */
  username?: string;
  /** The signed-in admin changes their own password. */
  own?: boolean;
  done: (r: PasswordResult | null) => void;
}>();

const create = computed(() => !props.username);
const user = ref('');
const password = ref('');
const generate = ref(true);
const reveal = ref(false);
const busy = ref(false);
const tried = ref(false);
const serverError = ref<string | null>(null);
const userInput = ref<HTMLInputElement | null>(null);
const pwInput = ref<HTMLInputElement | null>(null);

const userError = computed(() => (create.value && tried.value && !user.value.trim() ? t('Username required') : null));
const pwError = computed(() => {
  if (generate.value || (!tried.value && !password.value)) return null;
  const p = passwordProblem(password.value);
  if (p === 'short') return t('At least {n} characters', { n: MIN_PASSWORD_LENGTH });
  if (p === 'long') return t('At most {n} bytes (bcrypt limit)', { n: MAX_PASSWORD_BYTES });
  return null;
});

const title = computed(() => (create.value ? t('Add admin') : props.own ? t('Change password') : t('Reset password')));
const subtitle = computed(() =>
  create.value
    ? t('Admins have full control over every bucket on this server.')
    : props.own
      ? t('Your other sessions end; this app signs in again with the new password.')
      : t('Signs “{u}” out of every active session.', { u: props.username ?? '' }),
);

onMounted(() => (create.value ? userInput.value : null)?.focus());

async function setGenerate(v: boolean) {
  generate.value = v;
  if (!v) {
    await nextTick();
    pwInput.value?.focus();
  }
}

async function submit() {
  if (busy.value) return;
  tried.value = true;
  serverError.value = null;
  const name = create.value ? user.value.trim() : props.username!;
  if (create.value && !name) return;
  if (!generate.value && passwordProblem(password.value)) return;
  const requested = generate.value ? '' : password.value;
  busy.value = true;
  try {
    const api = useApi();
    const answer = create.value ? await api.addAdmin(name, requested || undefined) : await api.setAdminPassword(name, requested || undefined);
    props.done(toPasswordResult(answer, name, requested));
  } catch (e) {
    serverError.value = (e as Error).message;
    busy.value = false;
  }
}
</script>

<template>
  <Modal :width="440" :persistent="busy" @close="done(null)">
    <template #header>
      <div class="head">
        <div class="ic"><UserPlus v-if="create" :size="17" /><KeyRound v-else :size="17" /></div>
        <div class="grow">
          <h2>{{ title }}</h2>
          <p class="t-body-sm">{{ subtitle }}</p>
        </div>
      </div>
    </template>

    <form class="col form" @submit.prevent="submit">
      <div v-if="create" class="field">
        <label for="adm-user">{{ t('Username') }}</label>
        <input id="adm-user" ref="userInput" v-model="user" class="input" :class="{ invalid: userError }" autocomplete="off" spellcheck="false" :disabled="busy" />
        <span v-if="userError" class="error">{{ userError }}</span>
      </div>
      <div v-else class="field">
        <label>{{ t('Username') }}</label>
        <div class="fixed mono selectable">{{ username }}</div>
      </div>

      <label class="gen">
        <span class="grow">{{ t('Generate a strong password') }}</span>
        <Toggle :model-value="generate" :disabled="busy" @update:model-value="setGenerate" />
      </label>

      <div v-if="!generate" class="field">
        <label for="adm-pw">{{ t('Password') }}</label>
        <div class="pw">
          <input
            id="adm-pw" ref="pwInput" v-model="password" class="input" :class="{ invalid: pwError }" :type="reveal ? 'text' : 'password'"
            autocomplete="new-password" spellcheck="false" :disabled="busy"
          />
          <button type="button" class="btn ghost icon sm eye" :title="reveal ? t('Hide') : t('Show')" @click="reveal = !reveal">
            <EyeOff v-if="reveal" :size="15" /><Eye v-else :size="15" />
          </button>
        </div>
        <span v-if="pwError" class="error">{{ pwError }}</span>
        <span v-else class="hint">{{ t('8+ characters, max 72 bytes') }}</span>
      </div>

      <Callout v-if="serverError" tone="danger">{{ serverError }}</Callout>
      <button type="submit" hidden />
    </form>

    <template #footer>
      <button class="btn" :disabled="busy" @click="done(null)">{{ t('Cancel') }}</button>
      <button class="btn primary" :disabled="busy" @click="submit">
        <Spinner v-if="busy" :size="14" />
        {{ create ? t('Add admin') : own ? t('Change password') : t('Reset password') }}
      </button>
    </template>
  </Modal>
</template>

<style scoped>
.head { flex: 1; display: flex; align-items: flex-start; gap: 12px; min-width: 0; }
.head h2 { font-size: 16px; font-weight: 700; letter-spacing: -0.2px; }
.ic { width: 34px; height: 34px; border-radius: var(--radius-md); background: var(--primary-soft); color: var(--primary); display: grid; place-items: center; flex-shrink: 0; }
.form { gap: 14px; }
.fixed { padding: 8px 12px; border-radius: var(--radius-md); background: var(--hover); border: 1px solid var(--border); }
.gen { display: flex; align-items: center; gap: 12px; font-size: 13.5px; cursor: pointer; }
.pw { position: relative; }
.pw .input { padding-right: 40px; }
.eye { position: absolute; right: 4px; top: 4px; }
</style>
